import six
from os import path


from ute_admin_infomodel.event import ResetEvent, RemoveEvent, UpdateEvent
from ute_admin_infomodel.event.factory import EventMatcherFactory
from ute_admin_infomodel.listener import InfoModelChangeListener
from ute_admin_infomodel.exception import InfoModelIms2ValidationException, InfoModelIms2ReaderException

from .provider import Ims2DataProvider


def _prepare_error_message(unsatisfied_matchers):
    error_msg = ""
    for event_macher in unsatisfied_matchers:
        occurences = _prepare_occurences_log(event_macher.get_occurences())
        error_msg += "\nEXPECTED EVENT: %s\nACTUAL OCCURENCES:%s\n" % (event_macher, occurences)
    return error_msg


def _prepare_occurences_log(occurences):
    log = ""
    for occurence in occurences:
        log += "\n%s: %s %s" % (occurence["timestamp"], occurence["action"], occurence["dist_name"])
    return log


class Ims2EventTracer(InfoModelChangeListener):

    def __init__(self):
        self.event_matchers = []

    def add_event_matcher(self, event_matcher):
        """Add evnent matcher."""
        self.event_matchers.append(event_matcher)

    def clear_event_matchers(self):
        """Clear event matchers."""
        del self.event_matchers[:]

    def on_reset(self, timestamp):
        """Called when connection reset."""
        self._notify(ResetEvent(timestamp))

    def on_remove(self, removed, timestamp):
        """Called when infomodel object is removed."""
        self._notify(RemoveEvent(removed, timestamp))

    def on_update(self, updated, timestamp):
        """Called when infomodel object changes."""
        self._notify(UpdateEvent(updated, timestamp))

    def _notify(self, event):
        for event_macher in self.event_matchers:
            event_macher.match(event)


class Ims2EventReader(object):

    def __init__(self):
        self.factory = EventMatcherFactory()
        self.event_tracer = Ims2EventTracer()
        self.data_provider = None

    def _open_ims2(self, ims2_file_path):
        if not path.isfile(ims2_file_path):
            raise InfoModelIms2ReaderException("File not found: '%s'" % ims2_file_path)
        self.data_provider = Ims2DataProvider(ims2_file_path, self.event_tracer)

    def _read_ims2_data(self):
        if not self.data_provider:
            raise InfoModelIms2ReaderException("IMS2 reader is uninitialized.")
        self.data_provider.run()

    def _add_traced_event(self, event):
        event_matcher = self.factory.create_event_matcher(event)
        self.event_tracer.add_event_matcher(event_matcher)
        return event_matcher

    def _add_traced_event_sequence(self, events):
        sequence_matcher = self.factory.create_event_sequence_matcher(events)
        self.event_tracer.add_event_matcher(sequence_matcher)
        return sequence_matcher

    def _get_traced_events_matchers(self):
        return self.event_tracer.event_matchers

    def _clear_traced_events(self):
        self.event_tracer.clear_event_matchers()


class Ims2Validator(Ims2EventReader):

    def __init__(self):
        Ims2EventReader.__init__(self)

    def initialize(self, ims2_file_path):
        """Prepare IMS2 data provider."""
        self._open_ims2(ims2_file_path)

    def expect_event(self, event):
        """Expected event."""
        self._add_traced_event(event)

    def expect_event_sequence(self, events):
        """Expected event sequence."""
        self._add_traced_event_sequence(events)

    def validate(self):
        """Read IMS2 content and verify expectations."""
        self._read_ims2_data()
        unsatisfied_matchers = [event_macher for event_macher in self._get_traced_events_matchers() if not event_macher.satisfied()]
        self._clear_traced_events()
        if unsatisfied_matchers:
            raise InfoModelIms2ValidationException(_prepare_error_message(unsatisfied_matchers))


class Ims2ChangeSetProvider(Ims2EventReader):

    def __init__(self):
        Ims2EventReader.__init__(self)

    def get_change_sets(self, ims2_file_path, event):
        """Read IMS2 file content and get change sets matching event."""
        self._open_ims2(ims2_file_path)
        event_matcher = self._add_traced_event(event)
        self._read_ims2_data()
        self._clear_traced_events()
        return event_matcher.get_occurences()

    def get_multiple_change_sets(self, ims2_file_path, events):
        """Read IMS2 file content and get change sets matching events."""

        event_keys = {}
        for key, event in six.iteritems(events):
            event_matcher = self._add_traced_event(event)
            event_keys[event_matcher] = key

        self._open_ims2(ims2_file_path)
        self._read_ims2_data()

        result = {}
        for event_matcher in self._get_traced_events_matchers():
            key = event_keys[event_matcher]
            result[key] = event_matcher.get_occurences()

        self._clear_traced_events()
        return result
